/** Total number of skills in the registry */
export const SKILLS_REGISTRY_COUNT = SKILLS_REGISTRY.length;

/** Get skills by category */
export function getSkillsByCategory(category: SkillCategory): SkillRegistryEntry[] {
  return SKILLS_REGISTRY.filter((s) => s.category === category);
}

/** Search skills by query (matches name, description, or slug) */
export function searchSkills(query: string): SkillRegistryEntry[] {
  if (!query) {
    return [];
  }
  const q = query.toLowerCase();
  return SKILLS_REGISTRY.filter(
    (s) =>
      s.name.toLowerCase().includes(q) ||
      s.description.toLowerCase().includes(q) ||
      s.slug.toLowerCase().includes(q)
  );
}
